import React, { useEffect, useState } from 'react';
import { fetchSchoolDashboard, SchoolDashboardStats } from '../api';

const SchoolDashboard: React.FC = () => {
  const [stats, setStats] = useState<SchoolDashboardStats | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchSchoolDashboard()
      .then(setStats)
      .catch((e) => setError(e instanceof Error ? e.message : '加载失败'));
  }, []);

  if (error) {
    return <div className="school-card school-error">{error}</div>;
  }
  if (!stats) {
    return <div className="school-card">正在加载看板数据…</div>;
  }

  return (
    <div className="school-dashboard">
      <h2>数据看板</h2>
      <div className="school-stat-grid">
        <div className="school-stat-card">
          <span className="label">累计咨询</span>
          <strong>{stats.totalConsultations}</strong>
        </div>
        <div className="school-stat-card">
          <span className="label">活跃学生</span>
          <strong>{stats.activeStudents}</strong>
        </div>
        <div className="school-stat-card warn">
          <span className="label">高危记录</span>
          <strong>{stats.highRiskCount}</strong>
        </div>
        <div className="school-stat-card alert">
          <span className="label">待处理告警</span>
          <strong>{stats.pendingAlerts}</strong>
        </div>
        <div className="school-stat-card">
          <span className="label">平均压力指数</span>
          <strong>{stats.avgStress}</strong>
        </div>
      </div>

      <div className="school-two-col">
        <div className="school-card">
          <h3>问题类型 Top3</h3>
          {stats.problemTop3.length === 0 && <p className="muted">暂无数据</p>}
          <ul className="school-rank-list">
            {stats.problemTop3.map((item) => (
              <li key={item.category}>
                <span>{item.category}</span>
                <span>{item.count} 次 · {item.share}%</span>
              </li>
            ))}
          </ul>
        </div>
        <div className="school-card">
          <h3>情绪分布 Top3</h3>
          {stats.emotionTop3.length === 0 && <p className="muted">暂无数据</p>}
          <ul className="school-rank-list">
            {stats.emotionTop3.map((item) => (
              <li key={item.emotion}>
                <span>{item.emotion}</span>
                <span>{item.count} 次 · {item.share}%</span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
};

export default SchoolDashboard;
